caller actual github.com/volvo-cars/cce-prins-validator/internal/gateway/prins#Client.GetStoredCpvSets(context.Context,string,string,int)->(PrinsQueryResponse,error) Source constant storedCpvSetsQueryDocument = `query StoredCpvSetsQuery(
	$offset: Int!,
	$limit: Int!,
	$configDictionaryName: String!,
	$specMarket: String,
	$modelYear: String
) {
	storedCpvSets(
		where: {
			configurationDictionary: {
				name: $configDictionaryName
			}
			NOT:{status:"Obsolete"}
			specMarkets_SOME: { name: $specMarket }
			modelYear_STARTS_WITH: $modelYear
		},
		options: {
			limit: $limit,
			offset: $offset,
		}
	)

	{
		status
		modelYear
		pno
		effectiveInWeek
		effectiveOutWeek
	}
}
`

